<template>
 <main class="rules-page" v-loading="loading">
  <header class="rules-header"><div><span class="eyebrow">{{ isLedger?'记账本 · 支出规则':'外卖视角 · 费用规则' }}</span><h2>{{ isLedger?'记账本字段分配':'外卖字段分类' }}</h2><p>{{ isLedger?'按支出性质分配标签，保留原始名称与历史记录。':'保留平台原始名称，外卖开销只归入第三方手续费或推广费。' }}</p></div><div><el-button :disabled="dirty" @click="load">重新读取</el-button><el-button type="primary" :disabled="!dirty" :loading="saving" @click="save">保存{{ isLedger?'字段分配':'人工分类' }}</el-button></div></header>
  <section class="summary"><div><b>{{ isLedger?'四类支出标签':'三个外卖平台' }}</b><span>{{ isLedger?'实支 · 均摊 · 总部 · 平台':'美团外卖 · 淘宝闪购 · 京东外卖' }}</span></div><div><b>{{ rows.length }} 个字段</b><span>{{ isLedger?`${rows.filter(r=>r.deprecated).length} 个弃用字段排在末尾`:`${rows.filter(r=>!r.fixed&&r.category==='unconfirmed').length} 个字段待确认` }}</span></div><div><b>{{ dirty?'有未保存修改':'修改后手动保存' }}</b><span>{{ isLedger?'保存标签不会启用外卖人工分类':enabled?'人工分类已启用':'未启用，计算保持已有口径' }}</span></div></section>
  <section class="rules-card"><el-tabs v-if="!isLedger" v-model="platform"><el-tab-pane v-for="name in platforms" :key="name" :name="name" :label="name"/></el-tabs>
   <div class="filters"><el-input v-model="search" clearable placeholder="搜索字段名称" aria-label="搜索字段"/><el-select v-model="filter" aria-label="筛选分类"><el-option label="全部分类" value=""/><el-option v-for="(label,key) in categories" :key="key" :label="label" :value="key"/></el-select><el-select v-if="isLedger" v-model="status" aria-label="字段状态"><el-option label="全部字段" value=""/><el-option label="常用字段" value="active"/><el-option label="弃用字段" value="deprecated"/></el-select><span>匹配 {{ filtered.length }} 项</span></div>
   <el-table :data="paged" stripe row-key="key" :row-class-name="({row})=>row.deprecated?'deprecated-row':''"><el-table-column v-if="isLedger" prop="category_name" label="记账大类" min-width="160"/><el-table-column :label="isLedger?'记账子字段':'平台原始子字段'" min-width="260"><template #default="{row}">{{ isLedger?row.subcategory_name:row.name }}<el-tag v-if="row.deprecated" type="info" size="small" class="deprecated-tag">弃用</el-tag></template></el-table-column><el-table-column v-if="!isLedger" label="数据来源" width="120"><template #default="{row}"><el-tag :type="row.source==='bill'?'info':'warning'" effect="plain">{{ row.source==='bill'?'平台账单':'额外开销' }}</el-tag></template></el-table-column><el-table-column prop="records" label="历史记录" width="110" align="right"/><el-table-column :label="isLedger?'支出标签':'人工分类'" min-width="240"><template #default="{row}"><span v-if="row.fixed" class="muted">{{ row.fixed_label || categories[row.category] || '平台订单收入' }}<el-tag size="small" type="info" effect="plain" style="margin-left:8px">固定</el-tag></span><el-select v-else :model-value="isLedger?row.type:row.category" :aria-label="`${isLedger?row.subcategory_name:row.name}分类`" @update:model-value="value=>change(row,value)"><el-option v-for="(label,key) in rowChoices(row)" :key="key" :label="label" :value="key" :disabled="isLedger&&key==='accrual'&&!row.can_accrue"/></el-select></template></el-table-column></el-table>
   <footer><span>共 {{ filtered.length }} 项</span><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :page-sizes="[10,20,50]" :total="filtered.length" layout="sizes, prev, pager, next" background/></footer>
  </section>
  <section class="notes" v-if="isLedger"><b>标签含义</b><p>实支：按实际发生日，食材及日常报销不均摊。均摊：房租、水电、工资等固定费用按所选月份分摊。</p><p>总部：总部运营费、管理费，目前沿用记录金额。平台：第三方平台扣费，核对后台已扣金额，避免重复扣减。弃用字段保留历史分类，排在最后。</p></section><section class="notes" v-else><b>退款与费用如何分类</b><p>订单退款或订单赔付固定为“实收退款／赔付调整”，只调整实收；推广退款选择“推广费”，保险或第三方费用退款选择“第三方手续费”，以原始正负金额冲减对应费用。订单退款／赔付分类固定，不允许人工修改。</p><p>余额变动作为推广充值时选择“推广费”。霸王餐是原始开销名称，归入推广费，不单列费用类别。“待确认”表示尚未完成分类。团购不参与此设置。</p></section>
 </main>
</template>
<script setup>
import {ref,computed,onMounted,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {getDeliveryFeeRules,saveDeliveryFeeRules,getBookkeepingExpenseTags,saveBookkeepingExpenseTags} from '@/api'
const props=defineProps({mode:{type:String,default:'delivery'}}),isLedger=computed(()=>props.mode==='ledger')
const platform=ref('美团外卖'),platforms=['美团外卖','淘宝闪购','京东外卖'],rows=ref([]),categories=ref({}),revision=ref(0),enabled=ref(false),dirty=ref(false),loading=ref(false),saving=ref(false),search=ref(''),filter=ref(''),status=ref(''),page=ref(1),pageSize=ref(10)
const filtered=computed(()=>rows.value.filter(r=>(isLedger.value||r.platform===platform.value)&&(!filter.value||(isLedger.value?r.type:r.category)===filter.value)&&(!status.value||(status.value==='deprecated')===Boolean(r.deprecated))&&`${r.name||''} ${r.category_name||''} ${r.subcategory_name||''}`.toLowerCase().includes(search.value.toLowerCase())))
const paged=computed(()=>filtered.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value))
watch([platform,search,filter,status,pageSize],()=>page.value=1)
function rowChoices(){return isLedger.value?categories.value:Object.fromEntries(Object.entries(categories.value).filter(([key])=>['third_party','promotion','unconfirmed'].includes(key)))}
function change(row,value){if(row.fixed)return;row[isLedger.value?'type':'category']=value;dirty.value=true}
function apply(d){rows.value=isLedger.value?d.ledger_rows:d.rows;categories.value=isLedger.value?d.ledger_types:d.categories;revision.value=d.revision;enabled.value=d.enabled;dirty.value=false}
async function load(){loading.value=true;try{apply(await(isLedger.value?getBookkeepingExpenseTags():getDeliveryFeeRules()))}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}
async function save(){saving.value=true;try{const body=isLedger.value?{revision:revision.value,ledger_rows:rows.value.map(({key,type})=>({key,type}))}:{revision:revision.value,rows:rows.value.filter(r=>!r.fixed).map(({key,category})=>({key,category}))};apply(await(isLedger.value?saveBookkeepingExpenseTags(body):saveDeliveryFeeRules(body)));ElMessage.success('已保存，请重新查询看板或生成日报')}catch(e){ElMessage.error(e.message)}finally{saving.value=false}}
onMounted(load)
</script>
<style scoped>
.rules-page{max-width:1440px;margin:auto;padding:8px 0 24px}.rules-header{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-bottom:22px}.eyebrow{font-size:12px;color:var(--el-color-primary);font-weight:600}.rules-header h2{font-size:25px;margin:8px 0}.rules-header p,.summary span,.notes p,.muted{font-size:13px;color:var(--el-text-color-secondary);line-height:1.8;margin:0}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:20px}.summary>div{background:var(--el-bg-color);border:1px solid var(--el-border-color-light);border-radius:12px;padding:18px 22px}.summary b,.summary span{display:block}.summary b{font-size:15px;margin-bottom:6px}.rules-card{background:var(--el-bg-color);border:1px solid var(--el-border-color-light);border-radius:12px;padding:12px 22px 0;overflow:hidden}.filters{display:flex;gap:12px;align-items:center;padding:12px 0 20px}.filters>.el-input{max-width:340px}.filters>.el-select{width:170px}.filters>span{margin-left:auto;font-size:13px;color:var(--el-text-color-secondary);white-space:nowrap}.deprecated-tag{margin-left:8px}footer{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:18px 0;font-size:13px;color:var(--el-text-color-secondary)}.notes{margin-top:20px;border-left:3px solid var(--el-color-primary-light-5);padding:8px 18px}.notes>b{font-size:14px}.notes p{margin-top:8px}.rules-card :deep(.deprecated-row){color:var(--el-text-color-secondary)}.rules-card :deep(.el-table th){background:var(--el-fill-color-light);height:44px}.rules-card :deep(.el-table td){height:56px}.rules-card :deep(.el-select){max-width:235px}@media(max-width:850px){.rules-header{align-items:flex-start;flex-direction:column}.summary{grid-template-columns:1fr}.filters{flex-wrap:wrap}.filters>span{margin-left:0}footer{flex-wrap:wrap}.rules-card{padding:12px}}
</style>
